import concurrent.futures,json,urllib.error,urllib.request
BASE='https://app.ontrackegy.com/ayo/'
paths=['','index.php','style.css','app.js','ayo-avatar.js','ayo-mic-stt.js','assets/ayo-character.webp','api.php?action=status']
class NoRedirect(urllib.request.HTTPRedirectHandler):
 def redirect_request(self,req,fp,code,msg,headers,url): return None
opener=urllib.request.build_opener(NoRedirect())
def probe(path):
 req=urllib.request.Request(BASE+path,headers={'User-Agent':'OnTrack-AYO-HTTP-Smoke/1','Cache-Control':'no-cache'})
 try:
  with opener.open(req,timeout=7) as res:
   data=res.read(250000)
   header=res.headers.get('Permissions-Policy','')
   status=res.status
 except urllib.error.HTTPError as e: return {'path':path,'status':e.code,'redirect':e.headers.get('Location','')[:150],'ok':False}
 except Exception as e: return {'path':path,'error':type(e).__name__,'ok':False}
 if path in ('','index.php'): good=b'AYO | OnTrack Voice Lab' in data and b'enableMicBtn' in data
 elif path=='api.php?action=status':
  try: obj=json.loads(data);good=bool(obj.get('csrf')) and isinstance(obj.get('config'),dict)
  except Exception: good=False
 elif path=='assets/ayo-character.webp': good=data.startswith(b'RIFF') and data[8:12]==b'WEBP'
 elif path=='style.css':good=len(data)>1000
 else:good=len(data)>300
 return {'path':path,'status':status,'bytes':len(data),'ok':status==200 and good,'permissions_policy':header if path=='' else ''}
with concurrent.futures.ThreadPoolExecutor(max_workers=4) as p: out=list(p.map(probe,paths))
print(json.dumps({'all_ok':all(x['ok'] for x in out),'checks':out}),flush=True)
if not all(x['ok'] for x in out): raise SystemExit(2)
